import fs from 'node:fs';
import path from 'node:path';

const root=process.cwd();
const cssPath=path.join(root,'assets/css/site.css');
let css=fs.readFileSync(cssPath,'utf8');
const start='/* STAGE144B-FINAL-SPECIFICITY-AUTHORITY:START */';
const end='/* STAGE144B-FINAL-SPECIFICITY-AUTHORITY:END */';
if(css.includes(start)) css=css.replace(new RegExp(start.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'[\\s\\S]*?'+end.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\n?','g'),'');
const B='html body.apple-archive.apple-archive.apple-archive.apple-archive.apple-archive.apple-archive.apple-archive.apple-archive';
const block=`\n${start}\n/* Absolute final authority. Legacy rules in the historical archive intentionally\n   use repeated body classes; this layer outranks them without changing markup. */\n:root{\n  --art-bg:#202530!important;\n  --art-surface:#2D3444!important;\n  --art-surface-dark:#202530!important;\n  --art-surface-light:#2D3444!important;\n}\n\n${B}{background:#202530!important}\n${B} main{background:#202530!important}\n\n/* One editorial x-axis on every page and viewport. */\n${B} :is(main>header .wrap,main>header .wrap.narrow,main>section.wrap,main>section.wrap.narrow){\n  box-sizing:border-box!important;\n  width:min(calc(100% - (2 * var(--art-axis-gutter))),var(--art-axis-max))!important;\n  max-width:var(--art-axis-max)!important;\n  margin-left:auto!important;\n  margin-right:auto!important;\n  padding-left:0!important;\n  padding-right:0!important;\n}\n\n/* Exact approved two-blue rhythm. */\n${B} main>section{--banhalmi-section-surface:#202530!important;background:transparent!important}\n${B} main>section:nth-of-type(even){--banhalmi-section-surface:#2D3444!important}\n${B} main>section:nth-of-type(odd){--banhalmi-section-surface:#202530!important}\n${B} main>section::before{background:var(--banhalmi-section-surface)!important}\n\n/* Real content cells: minimum safe inset on both sides. */\n${B} :is(.t-item,.press-fact,.press-record,.facts>div){\n  box-sizing:border-box!important;\n  padding:var(--art-cell-pad-y) var(--art-cell-pad-x)!important;\n}\n${B} :is(.t-item,.press-record,.facts>div){background:#2D3444!important}\n${B}[data-archive-page="community"] .t-item{\n  width:min(100%,68rem)!important;\n  max-width:68rem!important;\n  padding:var(--art-cell-pad-y) var(--art-cell-pad-x)!important;\n  background:#2D3444!important;\n}\n\n/* Writing is a left-aligned editorial page, never a centred feature panel. */\n${B}[data-archive-page="writing"] main :is(header,section,h1,h2,h3,p,ul,li,.label,.loc,.lead,.facts,.linklist){text-align:left!important}\n${B}[data-archive-page="writing"] main>section>*{margin-left:0!important;margin-right:0!important}\n${B}[data-archive-page="writing"] main>section:nth-of-type(even)::before{background:#2D3444!important}\n${B}[data-archive-page="writing"] main>section:nth-of-type(odd)::before{background:#202530!important}\n\n/* Footer ecosystem: one mathematically centred row on desktop. */\n${B} footer .banhalmi-ecosystem{\n  position:static!important;inset:auto!important;transform:none!important;\n  height:auto!important;min-height:0!important;background:transparent!important;\n  border:0!important;box-shadow:none!important;box-sizing:border-box!important;\n  margin-left:auto!important;margin-right:auto!important;text-align:center!important;\n}\n@media(min-width:900px){\n  ${B} footer .banhalmi-ecosystem{\n    width:min(calc(100% - 40px),48rem)!important;max-width:48rem!important;\n    display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;\n    gap:clamp(18px,2.5vw,32px)!important;align-items:center!important;justify-content:center!important;\n  }\n  ${B} footer .banhalmi-ecosystem>a{\n    display:flex!important;width:100%!important;min-width:0!important;min-height:44px!important;\n    align-items:center!important;justify-content:center!important;margin:0!important;padding:8px 0!important;\n    text-align:center!important;white-space:nowrap!important;\n  }\n}\n@media(max-width:760px){\n  ${B} :is(main>header .wrap,main>header .wrap.narrow,main>section.wrap,main>section.wrap.narrow){\n    width:calc(100% - 40px)!important;max-width:none!important;\n  }\n  ${B} :is(.t-item,.press-fact,.press-record,.facts>div){padding-left:18px!important;padding-right:18px!important}\n}\n${end}\n`;
css=css.trimEnd()+block+'\n';
fs.writeFileSync(cssPath,css);

const auditPath=path.join(root,'tools/audit-first-principles-layout.mjs');
let audit=fs.readFileSync(auditPath,'utf8');
audit=audit.replace("document.querySelectorAll('.t-item,.press-fact,.press-record,.facts>div,[class$=\"__card\"]')","document.querySelectorAll('.t-item,.press-fact,.press-record,.facts>div')");
fs.writeFileSync(auditPath,audit);

for(const rel of ['tools/one-shot-stage144b-specificity-20260815.mjs','.github/workflows/one-shot-stage144b-specificity-20260815.yml']){const p=path.join(root,rel);if(fs.existsSync(p))fs.rmSync(p)}
console.log('Stage144B final specificity authority applied.');
